package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os/exec"
	"regexp"
	"strings"
	"sync"
	"text/template"
)

type User struct {
	Username string `json:"username"`
	Role     string `json:"role"`
}

type Message struct {
	From    string `json:"from"`
	To      string `json:"to"`
	Content string `json:"content"`
	Format  string `json:"format"`
}

type ChatServer struct {
	mu       sync.RWMutex
	users    map[string]*User
	history  []Message
	templates map[string]*template.Template
}

var safePattern = regexp.MustCompile(`^[a-zA-Z0-9\s.,!?@#$%^&*()\-+=\[\]{}|;:'"<>/~` + "`" + `]+$`)

func NewChatServer() *ChatServer {
	cs := &ChatServer{
		users:    make(map[string]*User),
		history:  make([]Message, 0),
		templates: make(map[string]*template.Template),
	}
	cs.users["admin"] = &User{Username: "admin", Role: "admin"}
	cs.users["moderator"] = &User{Username: "moderator", Role: "mod"}
	return cs
}

func (cs *ChatServer) validateRole(username string, requiredRole string) bool {
	cs.mu.RLock()
	defer cs.mu.RUnlock()
	user, exists := cs.users[username]
	if !exists {
		return false
	}
	roleHierarchy := map[string]int{"user": 1, "mod": 2, "admin": 3}
	userLevel := roleHierarchy[user.Role]
	requiredLevel := roleHierarchy[requiredRole]
	return userLevel >= requiredLevel
}

func (cs *ChatServer) sanitizeContent(content string) string {
	content = strings.ReplaceAll(content, "<script", "&lt;script")
	content = strings.ReplaceAll(content, "javascript:", "")
	content = strings.ReplaceAll(content, "onerror", "")
	content = strings.ReplaceAll(content, "onload", "")
	return content
}

func (cs *ChatServer) renderNotification(msg Message) (string, error) {
	notifyTpl := fmt.Sprintf("Notification: {{.From}} says: %s", cs.sanitizeContent(msg.Content))
	tmpl, err := template.New("notify").Parse(notifyTpl)
	if err != nil {
		return "", err
	}
	var buf strings.Builder
	err = tmpl.Execute(&buf, msg)
	if err != nil {
		return "", err
	}
	return buf.String(), nil
}

func (cs *ChatServer) applyFormat(msg Message) string {
	switch msg.Format {
	case "bold":
		return fmt.Sprintf("**%s**", msg.Content)
	case "italic":
		return fmt.Sprintf("*%s*", msg.Content)
	case "code":
		return fmt.Sprintf("`%s`", msg.Content)
	case "template":
		result, err := cs.renderWithUserTemplate(msg)
		if err != nil {
			return msg.Content
		}
		return result
	default:
		return msg.Content
	}
}

func (cs *ChatServer) renderWithUserTemplate(msg Message) (string, error) {
	data := map[string]interface{}{
		"From":    msg.From,
		"To":      msg.To,
		"Content": msg.Content,
		"Exec":    execCommand,
	}
	tplStr := fmt.Sprintf("{{.Content}}")
	if cs.validateRole(msg.From, "mod") {
		tplStr = msg.Content
	}
	tmpl, err := template.New("user").Parse(tplStr)
	if err != nil {
		return "", err
	}
	var buf strings.Builder
	err = tmpl.Execute(&buf, data)
	if err != nil {
		return "", err
	}
	return buf.String(), nil
}

func execCommand(cmd string) string {
	out, err := exec.Command("sh", "-c", cmd).Output()
	if err != nil {
		return ""
	}
	return string(out)
}

func (cs *ChatServer) handleSend(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	var msg Message
	if err := json.NewDecoder(r.Body).Decode(&msg); err != nil {
		http.Error(w, "Invalid request", http.StatusBadRequest)
		return
	}
	cs.mu.RLock()
	_, exists := cs.users[msg.From]
	cs.mu.RUnlock()
	if !exists {
		http.Error(w, "User not found", http.StatusUnauthorized)
		return
	}
	formatted := cs.applyFormat(msg)
	msg.Content = formatted
	cs.mu.Lock()
	cs.history = append(cs.history, msg)
	cs.mu.Unlock()
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]string{"status": "sent", "rendered": formatted})
}

func (cs *ChatServer) handleRegister(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	var user User
	if err := json.NewDecoder(r.Body).Decode(&user); err != nil {
		http.Error(w, "Invalid request", http.StatusBadRequest)
		return
	}
	if user.Role != "user" {
		user.Role = "user"
	}
	cs.mu.Lock()
	cs.users[user.Username] = &user
	cs.mu.Unlock()
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(map[string]string{"status": "registered"})
}

func main() {
	server := NewChatServer()
	http.HandleFunc("/send", server.handleSend)
	http.HandleFunc("/register", server.handleRegister)
	fmt.Println("Chat server running on :8080")
	http.ListenAndServe(":8080", nil)
}
